arguments.file_text:
:root {
  color-scheme: light;
  --bg: #f5f7fb;
  --panel: #ffffff;
  --panel-alt: #eef3fa;
  --text: #1d2633;
  --muted: #596779;
  --primary: #2354d9;
  --primary-contrast: #ffffff;
  --danger: #b42318;
  --success: #067647;
  --warning: #b54708;
  --border: #d8e0ea;
  --focus: #0f62fe;
  --shadow: 0 12px 30px rgba(24, 39, 75, 0.1);
  --radius: 18px;
}

* { box-sizing: border-box; }
html, body { margin: 0; min-height: 100%; background: var(--bg); color: var(--text); font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; }
body { line-height: 1.45; }
img { max-width: 100%; }
a { color: var(--primary); }
button, input, select, textarea { font: inherit; }
button, input[type="submit"] { min-height: 44px; }
button, select, textarea, input { border-radius: 12px; border: 1px solid var(--border); background: #fff; color: var(--text); }
button { padding: 0.7rem 1rem; cursor: pointer; }
button.primary, input[type="submit"].primary { background: var(--primary); color: var(--primary-contrast); border-color: var(--primary); }
button.danger { background: #fff5f5; color: var(--danger); border-color: #f5c2c7; }
button.ghost { background: transparent; }
button:disabled, input:disabled, textarea:disabled, select:disabled { opacity: 0.6; cursor: not-allowed; }
button:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible, a:focus-visible, summary:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }

.skip-link { position: absolute; left: -9999px; top: 0; background: #fff; padding: 0.5rem 0.75rem; z-index: 1000; }
.skip-link:focus { left: 0.5rem; top: 0.5rem; }

#app { min-height: 100vh; }
.shell { display: grid; grid-template-rows: auto auto 1fr; min-height: 100vh; }
.topbar { position: sticky; top: 0; z-index: 10; background: rgba(245, 247, 251, 0.96); backdrop-filter: blur(10px); border-bottom: 1px solid var(--border); }
.topbar-inner { max-width: 1440px; margin: 0 auto; padding: 1rem; display: grid; gap: 0.75rem; }
.branding { display: flex; align-items: center; justify-content: space-between; gap: 1rem; flex-wrap: wrap; }
.branding h1 { font-size: clamp(1.4rem, 3vw, 2rem); margin: 0; }
.meta-row { display: flex; flex-wrap: wrap; gap: 0.75rem 1rem; align-items: center; color: var(--muted); font-size: 0.95rem; }
.pill { display: inline-flex; gap: 0.35rem; align-items: center; border: 1px solid var(--border); background: var(--panel); padding: 0.35rem 0.7rem; border-radius: 999px; }
.nav { display: flex; flex-wrap: wrap; gap: 0.5rem; }
.nav button[aria-current="page"] { background: var(--primary); color: var(--primary-contrast); border-color: var(--primary); }
.statusbar { display: flex; gap: 0.75rem; align-items: center; flex-wrap: wrap; font-size: 0.95rem; }
.statusbar strong { font-weight: 600; }
.status-live { padding: 0.6rem 0.8rem; background: var(--panel-alt); border: 1px solid var(--border); border-radius: 12px; min-height: 44px; display: flex; align-items: center; }

.main { max-width: 1440px; margin: 0 auto; padding: 1rem; display: grid; gap: 1rem; width: 100%; }
.view { display: grid; gap: 1rem; }
.card, .panel, .section-card { background: var(--panel); border: 1px solid var(--border); border-radius: var(--radius); box-shadow: var(--shadow); }
.card, .section-card { padding: 1rem; }
.grid { display: grid; gap: 1rem; }
.grid.two { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.grid.three { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.stack { display: grid; gap: 0.85rem; }
.row { display: flex; gap: 0.75rem; flex-wrap: wrap; align-items: center; }
.space-between { display: flex; justify-content: space-between; gap: 1rem; align-items: start; flex-wrap: wrap; }
.muted { color: var(--muted); }
.small { font-size: 0.92rem; }
.heading { margin: 0 0 0.25rem; font-size: 1.15rem; }
.subheading { margin: 0 0 0.75rem; color: var(--muted); }
.badge { display: inline-flex; align-items: center; border-radius: 999px; padding: 0.22rem 0.65rem; font-size: 0.83rem; font-weight: 600; border: 1px solid transparent; }
.badge.draft { background: #f0f7ff; color: #175cd3; border-color: #b2ddff; }
.badge.published { background: #ecfdf3; color: #027a48; border-color: #abefc6; }
.badge.in-progress { background: #fff7ed; color: #b54708; border-color: #fcd34d; }
.badge.submitted { background: #eef4ff; color: #3538cd; border-color: #c7d7fe; }
.badge.graded { background: #f0fdf4; color: #067647; border-color: #abefc6; }
.badge.released { background: #eaf6ff; color: #0b5cab; border-color: #a6d9ff; }
.badge.pending { background: #fff7ed; color: #b54708; border-color: #fcd34d; }
.badge.missing { background: #fef3f2; color: #b42318; border-color: #fecdca; }
.badge.excused { background: #f9f5ff; color: #6941c6; border-color: #d6bbfb; }
.badge.unweighted { background: #f2f4f7; color: #475467; border-color: #d0d5dd; }
.badge.ok { background: #ecfdf3; color: #027a48; border-color: #abefc6; }
.badge.warn { background: #fff7ed; color: #b54708; border-color: #fcd34d; }
.badge.err { background: #fef3f2; color: #b42318; border-color: #fecdca; }

form { display: grid; gap: 0.85rem; }
label { display: grid; gap: 0.35rem; font-weight: 600; }
input, select, textarea { width: 100%; padding: 0.8rem 0.9rem; background: #fff; }
textarea { min-height: 110px; resize: vertical; }
input[type="checkbox"], input[type="radio"] { width: auto; min-height: auto; }
fieldset { border: 1px solid var(--border); border-radius: 14px; padding: 0.85rem; }
legend { font-weight: 700; padding: 0 0.35rem; }
.helper { color: var(--muted); font-size: 0.92rem; }
.error { color: var(--danger); }
.success { color: var(--success); }

.list { display: grid; gap: 0.85rem; }
.list-item { padding: 1rem; background: var(--panel); border: 1px solid var(--border); border-radius: 16px; display: grid; gap: 0.75rem; }
.list-item header { display: flex; justify-content: space-between; gap: 1rem; flex-wrap: wrap; }
.list-item h3, .list-item h4, .list-item h5 { margin: 0; }
.list-item .actions { display: flex; gap: 0.5rem; flex-wrap: wrap; }
.compact { display: grid; gap: 0.45rem; }
.metrics { display: flex; flex-wrap: wrap; gap: 0.5rem 0.75rem; color: var(--muted); font-size: 0.92rem; }

.cards { display: grid; gap: 0.85rem; }
.cards.two { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.cards.three { grid-template-columns: repeat(3, minmax(0, 1fr)); }

.modal { max-width: min(980px, calc(100vw - 1rem)); width: 100%; border: none; border-radius: 20px; padding: 0; box-shadow: 0 30px 80px rgba(15, 23, 42, 0.3); }
.modal::backdrop { background: rgba(15, 23, 42, 0.48); }
.modal-inner { padding: 1rem; background: var(--panel); display: grid; gap: 1rem; }
.modal-inner .modal-head { display: flex; justify-content: space-between; gap: 1rem; align-items: start; }
.modal-content { display: grid; gap: 1rem; }
.modal-actions { display: flex; justify-content: flex-end; gap: 0.5rem; flex-wrap: wrap; }

.two-col { display: grid; gap: 1rem; grid-template-columns: minmax(0, 1fr) minmax(300px, 380px); }
.assessment-items, .attempt-items { display: grid; gap: 0.75rem; }
.item-card { border: 1px solid var(--border); border-radius: 14px; padding: 0.85rem; background: #fff; display: grid; gap: 0.6rem; }
.option-list { display: grid; gap: 0.45rem; margin: 0; padding: 0; list-style: none; }
.option-list label { display: flex; align-items: center; gap: 0.5rem; font-weight: 500; }
.inline-criteria { display: grid; gap: 0.5rem; }
.criteria-row, .worksheet-row { display: grid; grid-template-columns: auto minmax(0, 1fr) 110px minmax(0, 2fr); gap: 0.5rem; align-items: start; }
.worksheet-row { grid-template-columns: auto minmax(0, 1.4fr) 110px minmax(0, 1.8fr); }
.criteria-row textarea, .worksheet-row textarea { min-height: 74px; }

@media (max-width: 980px) {
  .grid.two, .grid.three, .cards.two, .cards.three, .two-col { grid-template-columns: 1fr; }
  .criteria-row, .worksheet-row { grid-template-columns: 1fr; }
}
@media (max-width: 640px) {
  .main, .topbar-inner { padding: 0.75rem; }
  .statusbar, .branding, .meta-row { align-items: stretch; }
  .nav button { flex: 1 1 0; }
  .card, .section-card { padding: 0.85rem; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; animation: none !important; transition: none !important; }
}

const app = document.getElementById('app');
const modal = document.getElementById('modal');

const state = {
  token: localStorage.getItem('coursemark_token') || '',
  user: null,
  workspace: null,
  view: 'courses',
  message: 'Ready.',
  messageKind: 'info',
  lastTrigger: null,
  modal: null,
  refreshing: false,
};

function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function safeText(value) {
  return escapeHtml(value ?? '');
}

function fmtDate(iso) {
  if (!iso) return '—';
  const date = new Date(iso);
  return new Intl.DateTimeFormat('en-GB', {
    timeZone: 'UTC',
    dateStyle: 'medium',
    timeStyle: 'short',
  }).format(date) + ' UTC';
}

function fmtNumber(value, digits = 2) {
  if (value === null || value === undefined || value === '') return '—';
  const num = Number(value);
  if (!Number.isFinite(num)) return '—';
  return num.toLocaleString('en-GB', { minimumFractionDigits: digits, maximumFractionDigits: digits });
}

function viewLabel(view) {
  return ({
    courses: 'Courses',
    assessments: 'Assessments',
    attempts: 'Attempts',
    gradebook: 'Gradebook',
    audit: 'Audit',
  })[view] || view;
}

function badge(label, cls) {
  return `<span class="badge ${cls}">${safeText(label)}</span>`;
}

function currentRevision() {
  return state.workspace?.course?.revision ?? 0;
}

function setMessage(message, kind = 'info') {
  state.message = message;
  state.messageKind = kind;
  const live = document.getElementById('status-live');
  if (live) live.textContent = message;
}

function showLogin(message = 'Sign in to continue.') {
  state.user = null;
  state.workspace = null;
  state.view = 'courses';
  state.message = message;
  state.messageKind = 'info';
  render();
}

function saveToken(token) {
  state.token = token;
  localStorage.setItem('coursemark_token', token);
}

function clearToken() {
  state.token = '';
  localStorage.removeItem('coursemark_token');
}

function operationId() {
  return crypto.randomUUID();
}

async function request(path, options = {}) {
  const headers = new Headers(options.headers || {});
  if (state.token && options.auth !== false) {
    headers.set('Authorization', `Bearer ${state.token}`);
  }
  if (options.body !== undefined) {
    headers.set('Content-Type', 'application/json');
  }
  if (options.write) {
    headers.set('X-Operation-Id', options.operationId || operationId());
    if (!options.signIn) headers.set('X-Coursemark-Revision', String(currentRevision()));
  } else if (options.signIn) {
    headers.set('X-Operation-Id', options.operationId || operationId());
  }
  const response = await fetch(path, {
    method: options.method || 'GET',
    headers,
    body: options.body !== undefined ? JSON.stringify(options.body) : undefined,
  });
  const text = await response.text();
  let data = null;
  if (text) {
    try {
      data = JSON.parse(text);
    } catch {
      data = { ok: false, error: { code: 'bad_json', message: text } };
    }
  }
  if (!response.ok) {
    const error = new Error(data?.error?.message || response.statusText || 'Request failed.');
    error.status = response.status;
    error.data = data;
    throw error;
  }
  return data;
}

function actionBusy(button, fn) {
  const target = button instanceof HTMLElement ? button : null;
  if (target) target.disabled = true;
  return Promise.resolve()
    .then(fn)
    .finally(() => {
      if (target) target.disabled = false;
    });
}

function openModal(html) {
  state.lastTrigger = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  modal.innerHTML = `<div class="modal-inner"><div class="modal-head">${html.head}<button type="button" class="ghost" data-action="close-modal">Close</button></div><div class="modal-content">${html.body}</div></div>`;
  modal.showModal();
  const focusTarget = modal.querySelector('[data-focus="true"]') || modal.querySelector('button, input, select, textarea');
  if (focusTarget) focusTarget.focus();
}

function closeModal() {
  if (modal.open) modal.close();
  modal.innerHTML = '';
  const trigger = state.lastTrigger;
  state.lastTrigger = null;
  if (trigger && typeof trigger.focus === 'function') trigger.focus();
  state.modal = null;
}

